-- V6__align_partner_uuid_to_partner_service.sql
-- dc-config-service 의 거래처 UUID를 partner-service canonical UUID로 치환한다.
-- 매핑키는 partner_code + biz_no이며, 대상 211행은 적용 시점의 read-only 실측 결과다.
-- 서로 다른 DB이므로 partner-service에서 추출한 canonical snapshot을 명시적으로 검증한다.
-- 모든 검증은 트랜잭션 안에서 수행되며 실패 시 FK/partners 변경 전체가 롤백된다.

CREATE TEMP TABLE partner_uuid_map (
    old_id UUID PRIMARY KEY,
    partner_code VARCHAR(100) NOT NULL,
    biz_no VARCHAR(100) NOT NULL,
    new_id UUID NOT NULL UNIQUE
) ON COMMIT DROP;


DO $$
DECLARE
    unmatched INTEGER;
    duplicate_key INTEGER;
    target_collision INTEGER;
BEGIN
    SELECT COUNT(*) INTO unmatched
      FROM partners p
      LEFT JOIN partner_uuid_map m
        ON m.old_id = p.id
       AND m.partner_code = p.partner_code
       AND m.biz_no = p.biz_no
     WHERE p.is_deleted = FALSE
       AND m.old_id IS NULL;
    IF unmatched <> 0 THEN
        RAISE EXCEPTION 'partner UUID migration mapping mismatch: unmatched active partners=%', unmatched;
    END IF;

    SELECT COUNT(*) INTO duplicate_key
      FROM (
        SELECT partner_code, biz_no
          FROM partner_uuid_map
         GROUP BY partner_code, biz_no
        HAVING COUNT(*) <> 1
      ) duplicates;
    IF duplicate_key <> 0 THEN
        RAISE EXCEPTION 'partner UUID migration mapping has duplicate business keys=%', duplicate_key;
    END IF;

    SELECT COUNT(*) INTO target_collision
      FROM partners p
      JOIN partner_uuid_map m ON m.new_id = p.id
     WHERE p.id <> m.old_id;
    IF target_collision <> 0 THEN
        RAISE EXCEPTION 'partner UUID migration target collision=%', target_collision;
    END IF;
END $$;

-- PostgreSQL은 새 부모 UUID가 아직 없을 때 child UPDATE를 거부한다.
-- 트랜잭션 안에서 FK를 잠시 해제하고 부모/자식을 함께 치환한 뒤 같은 제약을 재생성한다.
-- 실패하면 Flyway 트랜잭션 롤백으로 제약과 데이터가 모두 원복된다.
ALTER TABLE dc_configs DROP CONSTRAINT IF EXISTS dc_configs_partner_id_fkey;
ALTER TABLE dc_rules DROP CONSTRAINT IF EXISTS dc_rules_partner_id_fkey;

-- 현재 실측: dc_configs 211행, price_calculation_logs 49행,
-- dc_rules partner FK 0행. 각 UPDATE는 map에 없는 UUID를 건드리지 않는다.
UPDATE partners p
   SET id = m.new_id,
       modified_at = NOW(),
       modified_by = 'migration-v6-partner-uuid'
  FROM partner_uuid_map m
 WHERE p.id = m.old_id;

UPDATE dc_configs c
   SET partner_id = m.new_id
  FROM partner_uuid_map m
 WHERE c.partner_id = m.old_id;

UPDATE dc_rules r
   SET partner_id = m.new_id
  FROM partner_uuid_map m
 WHERE r.partner_id = m.old_id;

UPDATE price_calculation_logs l
   SET partner_id = m.new_id
  FROM partner_uuid_map m
 WHERE l.partner_id = m.old_id;

ALTER TABLE dc_configs
    ADD CONSTRAINT dc_configs_partner_id_fkey FOREIGN KEY (partner_id) REFERENCES partners(id);
ALTER TABLE dc_rules
    ADD CONSTRAINT dc_rules_partner_id_fkey FOREIGN KEY (partner_id) REFERENCES partners(id);

DO $$
DECLARE
    invalid_dc_configs INTEGER;
    invalid_dc_rules INTEGER;
    invalid_price_logs INTEGER;
    invalid_partners INTEGER;
BEGIN
    SELECT COUNT(*) INTO invalid_dc_configs
      FROM dc_configs c LEFT JOIN partners p ON p.id = c.partner_id
     WHERE p.id IS NULL;
    SELECT COUNT(*) INTO invalid_dc_rules
      FROM dc_rules r LEFT JOIN partners p ON p.id = r.partner_id
     WHERE r.partner_id IS NOT NULL AND p.id IS NULL;
    SELECT COUNT(*) INTO invalid_price_logs
      FROM price_calculation_logs l LEFT JOIN partners p ON p.id = l.partner_id
     WHERE l.partner_id IS NOT NULL AND p.id IS NULL;
    SELECT COUNT(*) INTO invalid_partners
      FROM partners p
      JOIN partner_uuid_map m ON m.new_id = p.id
     WHERE p.partner_code <> m.partner_code OR p.biz_no <> m.biz_no;

    IF invalid_dc_configs <> 0 OR invalid_dc_rules <> 0
       OR invalid_price_logs <> 0 OR invalid_partners <> 0 THEN
        RAISE EXCEPTION
          'partner UUID migration FK validation failed: dc_configs=%, dc_rules=%, price_logs=%, partners=%',
          invalid_dc_configs, invalid_dc_rules, invalid_price_logs, invalid_partners;
    END IF;
END $$;
